{"files":[{"file":"rtl/sequence.sv","content":"module TopModule(
    input wire clk,
    input wire rst,
    input wire d1,
    input wire d2,
    input wire sel,
    output reg out1,
    output reg out2,
    output reg out3
);

    reg [3:0] amount;
    reg d1_prev, d2_prev;
    reg add1, add2;
    integer next_amount;
    integer price;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            amount <= 0;
            d1_prev <= 0;
            d2_prev <= 0;
            out1 <= 0;
            out2 <= 0;
            out3 <= 0;
        end else begin
            add1 = d1 & ~d1_prev;
            add2 = d2 & ~d2_prev;
            d1_prev <= d1;
            d2_prev <= d2;

            next_amount = amount;
            if (add1) next_amount = next_amount + 1;
            if (add2) next_amount = next_amount + 2;

            price = sel ? 5 : 3;

            out1 <= 0;
            out2 <= 0;
            out3 <= 0;

            if (next_amount >= price) begin
                if (sel == 0) out1 <= 1;
                else out2 <= 1;
                if (next_amount > price) out3 <= 1;
                amount <= 0;
            end else begin
                amount <= next_amount;
            end
        end
    end

endmodule
"}],"edit":"Replace the FSM with a straightforward amount accumulator using edge detection for d1/d2, computing the price from sel, and generating one-cycle dispense pulses with change."}

